        UNION { VALUES ?root { wd:Q1478122 wd:Q1199602 wd:Q420904 wd:Q6138961 wd:Q3258688 wd:Q775963 wd:Q86719099 wd:Q181156 wd:Q137393393 wd:Q7574976 wd:Q7575197 wd:Q11254140 wd:Q3075281 wd:Q177929 wd:Q230872 wd:Q230924 wd:Q28057176 wd:Q1744628 wd:Q104633321 wd:Q7632171 } ?item wdt:P279 ?root }
